  "subtype": "focus_inference",
  "implied_focus": "The nature/type of recurring incidents -- characterizing each ticket by the kind of problem it represents (what domain, how widespread, how it was resolved)",
  "per_column": [
    {
      "name": "problem_domain",
      "supports_focus": true,
      "rationale": "Directly categorizes the type of problem (connectivity, email, database, etc.), which is the core of identifying recurring problem types."
    },
    {
      "name": "incident_scope",
      "supports_focus": true,
      "rationale": "Characterizes how broadly the problem manifests (system-wide vs individual), a coherent facet distinguishing kinds of recurring problems."
    },
    {
      "name": "resolution_complexity",
      "supports_focus": true,
      "rationale": "Captures the remediation pattern (server restart, infrastructure change, config update), another facet of the problem's nature and how it clusters into recurring types."
    }
  ],
  "focus_coherence": 0.85,
